SourceCode.Declaration:
/// <summary>
/// Holds the company-wide settings for the item identity display feature. A single record per
/// company stores the feature toggle, the default line label, the fallback behavior, and the
/// cache lifetime used by the resolver.
/// </summary>
public class AAXWHSItemIdentityParameters extends common
{
}

Method.Source:
/// <summary>
/// Finds the singleton parameters record, creating it when it does not exist yet.
/// </summary>
/// <param name = "_forUpdate">True to select the record for update.</param>
/// <returns>The parameters record.</returns>
public static AAXWHSItemIdentityParameters find(boolean _forUpdate = false)
{
    AAXWHSItemIdentityParameters parameters;

    parameters.selectForUpdate(_forUpdate);

    select firstonly parameters
        index KeyIdx
        where parameters.Key == 0;

    if (!parameters && !parameters.isTmp())
    {
        Company::createParameter(parameters);
    }

    return parameters;
}

/// <summary>
/// Initializes the parameters record with the documented defaults.
/// </summary>
public void initValue()
{
    super();

    this.DefaultLabel = "@AAXWarehouseTools:IdentityDefaultLabelValue";
    this.CacheTtlMinutes = 30;
    this.ExtContentDefault = AAXWHSItemIdentityExtContent::Id;
}

/// <summary>
/// Validates the parameters record before it is written. The external content default must
/// name a concrete content option.
/// </summary>
/// <returns>True if the record is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    // Default is reserved for profile lines
    if (this.ExtContentDefault == AAXWHSItemIdentityExtContent::Default)
    {
        ret = checkFailed(strFmt("@SYS119897", enum2Str(this.ExtContentDefault), fieldPName(AAXWHSItemIdentityParameters, ExtContentDefault)));
    }

    return ret;
}
